const demoClone = obj => JSON.parse(JSON.stringify(obj));
const demoState = demoClone(DEMO_BASE);
function demoMemberId(token) { const m = /^demo-member-(\d+)$/.exec(token || ''); return m ? m[1] : null; }
function demoActor(token) { const id=demoMemberId(token); return id ? demoState.members[id] : (token === 'demo-admin' ? demoState.admin : null); }
function demoDate() { return new Date().toLocaleDateString('sv-SE',{timeZone:'America/Sao_Paulo'}); }
function demoNow() { return Math.floor(Date.now()/1000); }
function demoRecalc() {
  const rank=demoState.public.ranking;
  rank.total_bookings=rank.members.reduce((n,m)=>n+(m.bookings||0),0);
  demoState.admin.admin.ranking=demoClone(rank);
}
window.demoApi = async function(path,options={},authToken='') {
  // Proibido chamar fetch() para API do servidor; toda a demonstração roda no próprio navegador.
  const parsed=new URL(path,'https://demo.invalid');
  const uri=parsed.pathname,method=(options.method||'GET').toUpperCase();
  let data={}; try{data=JSON.parse(options.body||'{}')}catch{data={}}
  const actor=demoActor(authToken),memberId=demoMemberId(authToken);
  const ok = value => demoClone(value);
  if (method==='GET') {
    if(uri==='/api/public') { demoRecalc(); return ok(demoState.public); }
    if(uri==='/api/session') { if(!actor) throw Error('Selecione um perfil de demonstração.'); return ok(actor.session); }
    if(uri==='/api/me') { if(!memberId) throw Error('Escolha uma consultora de demonstração.'); return ok(actor.me); }
    if(uri==='/api/crm') return ok(actor?.crm || demoState.admin.crm);
    if(uri==='/api/appointments')return ok(actor?.appointments || demoState.admin.appointments);
    if(uri==='/api/admin')return ok(demoState.admin.admin);
    if(uri==='/api/admin/report')return ok(demoState.admin.report);
    if(uri==='/api/admin/outcomes')return ok(demoState.admin.outcomes);
    if(uri==='/api/admin/alerts/report')return ok(demoState.admin.alertsReport);
    if(uri==='/api/admin/alerts/watch')return {events:[],last_event_id:demoState.admin.alerts.last_event_id};
    if(uri==='/api/admin/alerts')return ok(demoState.admin.alerts);
    if(uri==='/api/alerts')return {notices:[]};
    if(uri==='/api/ranking')return ok(demoState.public.ranking);
    throw Error('Esta função precisa do servidor da academia e não está disponível na demonstração.');
  }
  if(method==='POST') {
    if(uri==='/api/login')return {token:data.role==='member'?'demo-member-'+String(data.member_id||1):'demo-admin',role:data.role||'admin'};
    if(uri==='/api/logout')return {};
    if(uri==='/api/member/bookings') {
      if(!memberId)throw Error('Entre como consultora fictícia.');
      const delta=Number(data.delta)||0;
      actor.me.daily.bookings=Math.max(0,(actor.me.daily.bookings||0)+delta);
      actor.me.metrics.bookings=actor.me.daily.bookings;
      const rank=demoState.public.ranking.members.find(m=>String(m.id)===memberId);
      if(rank) rank.bookings=actor.me.daily.bookings;
      const report=demoState.admin.report.report.find(r=>String(r.member.id)===memberId);
      if(report){report.bookings=actor.me.daily.bookings;report.metrics.bookings=actor.me.daily.bookings;}
      return {ok:true};
    }
    if(uri==='/api/member/task') {
      if(!memberId)throw Error('Entre como consultora fictícia.');
      const task=actor.me.daily.tasks.find(t=>t.id===data.task_id);
      if(!task)throw Error('Bloco não encontrado nesta demonstração.');
      if(data.action==='complete'){task.done=true;task.started_at=null;task.elapsed=Math.max(task.elapsed||0,task.minutes*60);}
      if(data.action==='start'){task.started_at=demoNow();}
      if(data.action==='pause'){task.started_at=null;}
      if(data.action==='reset'){task.started_at=null;task.done=false;task.elapsed=0;}
      if(data.action==='count'){task.count=Math.max(0,(task.count||0)+Number(data.delta||0));}
      if(data.action==='note'){task.note=data.note||'';}
      actor.me.metrics.blocks=actor.me.daily.tasks.filter(t=>t.done).length;
      return {ok:true,early:false};
    }
    if(uri==='/api/member/notes'){if(memberId) actor.me.daily.notes=data.notes||'';return {ok:true};}
    if(uri==='/api/admin/alerts/schedule') {
      const row={id:demoNow()+Math.floor(Math.random()*1000),title:data.title,message:data.message,priority:data.priority,audience:data.audience,
      mode:data.mode,local_time:data.time,scheduled_day:data.date||null,weekdays:data.weekdays||[],end_date:data.end_date||null,
      next_run_at:Math.max(demoNow()+60,Math.floor(new Date((data.date||demoDate())+'T'+(data.time||'09:00')+':00-03:00').getTime()/1000)),
      active:true,last_sent_at:null,sent_count:0,skipped_count:0,completed_at:null};
      demoState.admin.alerts.schedules.unshift(row);return {schedule_id:row.id,next_run_at:row.next_run_at};
    }
    if(uri==='/api/admin/alerts/schedule-toggle') {
      const row=demoState.admin.alerts.schedules.find(s=>s.id===Number(data.schedule_id));if(row) row.active=!!data.active;return {ok:true};
    }
    if(uri==='/api/admin/alerts/send') {
      const now=demoNow(),id=now+Math.floor(Math.random()*1000);
      demoState.admin.alerts.notices.unshift({id,title:data.title||'Comunicado',message:data.message||'',priority:data.priority||'info',audience:data.audience||'all',created_at:now,delivered:0,confirmed:0,expected:0,receipts:[],web_reads:[]});
      const ev={id:++demoState.admin.alerts.last_event_id,notice_id:id,event_type:'sent',actor:'Sistema demonstrativo',title:data.title||'Comunicado',audience:data.audience||'all',happened_at:now};
      demoState.admin.alerts.activity.push(ev);demoState.admin.alertsReport.events.push(ev);
      return {ok:true};
    }
    if(uri==='/api/admin/alerts/pair')throw Error('Pareamento de receptores Windows só funciona no Missão Ouro instalado na academia.');
    if(uri==='/api/admin/alerts/device')return {ok:true};
    if(uri==='/api/admin/plan') {
      if(demoState.admin.admin.plans[data.shift])demoState.admin.admin.plans[data.shift]=demoClone(data.plan);
      return {ok:true};
    }
    if(uri==='/api/admin/member-plan'){
      const id=String(data.member_id);
      if(data.reset)delete demoState.admin.admin.member_plans[id];else demoState.admin.admin.member_plans[id]=demoClone(data.plan);
      return {ok:true};
    }
    if(uri==='/api/admin/template'){
      if(data.operation==='save')demoState.admin.admin.templates[data.name]=demoClone(data.plan);
      if(data.operation==='delete')delete demoState.admin.admin.templates[data.name];return {ok:true};
    }
    if(uri==='/api/admin/booking-adjust'){
      const row=demoState.admin.report.report.find(r=>r.member.id===Number(data.member_id));if(row){row.bookings=Number(data.bookings);row.metrics.bookings=Number(data.bookings);}
      const rank=demoState.public.ranking.members.find(r=>r.id===Number(data.member_id));if(rank)rank.bookings=Number(data.bookings);
      return {ok:true};
    }
    if(uri==='/api/admin/member'){
      throw Error('Cadastro real de funcionários não está disponível na apresentação pública.');
    }
    if(uri==='/api/crm/create'){
      if(!memberId)throw Error('Entre como consultora fictícia.');
      const newClient={id:demoNow(),name:data.name||'Cliente fictício',phone:data.phone||'000000',owner_id:Number(memberId),status:'green',stage:'active',note:'Cadastro de demonstração',first_contact_day:demoDate()};
      actor.crm.mine.unshift(newClient);return {ok:true};
    }
    if(uri==='/api/crm/outcome'){
      if(!memberId)throw Error('Entre como consultora fictícia.');
      const client=actor.crm.mine.find(c=>c.id===Number(data.client_id));
      if(client){client.status='closed';client.stage='closed';}
      return {message:data.result==='won'?'Plano fictício registrado!':'Perda fictícia registrada!'};
    }
    if(uri==='/api/crm/book')return {ok:true};
    if(uri==='/api/crm/claim')return {ok:true};
    if(uri==='/api/crm/followup')return {ok:true};
    if(uri==='/api/crm/cancel')return {ok:true};
    if(uri==='/api/alerts/ack')return {ok:true};
    throw Error('Função ilustrativa indisponível nesta demonstração estática.');
  }
  throw Error('Operação não suportada na demonstração.');
};
window.missaoDemoSwitch = async function(role){
  window.localStorage.setItem('missao.demo.token',role);
  location.reload();
};
window.missaoDemoReset = function(){window.localStorage.removeItem('missao.demo.token');location.reload();};
